// Pega o csv como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "") || 0);

  return obj;
});

return [{ json: {investimentos} }];

const entrada = $input.all();

const dados = entrada[0]?.json ?? {};

// Recupera as listas que chegam do Webhook/Merge
const clientes = dados.body?.clientes ?? dados.clientes;
const investimentos = dados.investimentos;

if (!Array.isArray(clientes)) {
  throw new Error(
    "A lista de clientes não foi encontrada. Verifique a saída do Merge."
  );
}

if (!Array.isArray(investimentos)) {
  throw new Error(
    "A lista de investimentos não foi encontrada. Verifique a saída do Merge."
  );
}

// Converte valores monetários como "R$ 12.500,00"
function paraNumero(valor) {
  if (typeof valor === "number") return valor;

  const texto = String(valor ?? "")
    .replace(/R\$\s?/g, "")
    .replace(/\./g, "")
    .replace(",", ".")
    .trim();

  return Number(texto) || 0;
}

function normalizar(texto) {
  return String(texto ?? "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .trim()
    .toLowerCase();
}

return clientes.map(cliente => {
  const nome = cliente.nome ?? "Cliente";
  const email = cliente.email ?? "";
  const saldo = paraNumero(cliente.saldo);
  const perfil = normalizar(cliente.perfil);

  // Seleciona investimentos do mesmo perfil cujo mínimo cabe no saldo
  const opcoes = investimentos.filter(inv => {
    const mesmoPerfil = normalizar(inv.perfil) === perfil;
    const minimo = paraNumero(inv.minimo);

    return mesmoPerfil && minimo <= saldo;
  });

  // Mantém todas as opções compatíveis para este cliente
  const recomendacoes = opcoes.map(inv => ({
    produto: inv.produto,
    rentabilidade: inv.rentabilidade,
    minimo: inv.minimo
  }));

  let mensagem;

  if (recomendacoes.length > 0) {
    const lista = recomendacoes.map(inv =>
      `${inv.produto} (rentabilidade informada: ${inv.rentabilidade}; mínimo: R$ ${paraNumero(inv.minimo).toLocaleString("pt-BR", {minimumFractionDigits: 2})})`
    ).join("; ");

    mensagem =
      `Olá, ${nome}! Considerando seu perfil ${cliente.perfil} ` +
      `e o saldo informado de R$ ${saldo.toLocaleString("pt-BR", {minimumFractionDigits: 2})}, ` +
      `estas são as opções da base que correspondem ao seu perfil ` +
      `e respeitam o investimento mínimo: ${lista}. ` +
      `Rentabilidades não são garantidas; avalie os riscos e as condições de cada produto.`;
  } else {
    mensagem =
      `Olá, ${nome}! Considerando seu perfil ${cliente.perfil} ` +
      `e o saldo informado, não encontramos investimentos desse perfil ` +
      `cujo mínimo esteja dentro do saldo disponível na base consultada.`;
  }

  return {
    json: {
      nome,
      email,
      saldo: cliente.saldo,
      perfil: cliente.perfil,
      investimentos: recomendacoes,
      assunto: `Sugestões de investimento para ${nome}`,
      mensagem
    }
  };
});

const respostas = $input.all();
const clientes = $("Normalizar clientes").all();

function escaparHTML(valor) {
  return String(valor ?? "").replace(/[&<>"']/g, c => ({
    "&": "&amp;",
    "<": "&lt;",
    ">": "&gt;",
    '"': "&quot;",
    "'": "&#39;"
  })[c]);
}

function obterTexto(obj) {
  // Formatos comuns de saída do OpenAI no n8n
  const candidatos = [
    obj.output,
    obj.text,
    obj.content,
    obj.message,
    obj.response
  ];

  for (const valor of candidatos) {
    if (typeof valor === "string" && valor.trim()) {
      return valor.trim();
    }

    if (valor && typeof valor === "object") {
      if (typeof valor.text === "string") {
        return valor.text.trim();
      }

      if (typeof valor.content === "string") {
        return valor.content.trim();
      }
    }
  }

  // Algumas versões retornam conteúdo em blocos
  const blocos = obj.output?.[0]?.content;

  if (Array.isArray(blocos)) {
    return blocos
      .map(bloco => bloco.text ?? "")
      .join("\n")
      .trim();
  }

  return "";
}

return respostas.map((item, index) => {
  const cliente = clientes[index]?.json ?? {};
  const texto = obterTexto(item.json);

  if (!texto) {
    throw new Error(
      `A resposta do OpenAI está vazia para o cliente ${cliente.nome ?? index + 1}.`
    );
  }

  // Escapa HTML e transforma quebras de linha em parágrafos
  const corpo = escaparHTML(texto)
    .replace(/\r\n/g, "\n")
    .replace(/\r/g, "\n")
    .split(/\n{2,}/)
    .map(paragrafo =>
      `<p style="margin:0 0 16px;line-height:1.7;">${paragrafo.replace(/\n/g, "<br>")}</p>`
    )
    .join("\n");

  const nome = escaparHTML(cliente.nome ?? "Cliente");

  const html = `
<div style="font-family:Arial,Helvetica,sans-serif;color:#333333;font-size:15px;max-width:640px;margin:0 auto;padding:24px;">
  <h2 style="color:#245b4a;font-size:21px;margin:0 0 24px;">
    Informações sobre investimentos
  </h2>
  ${corpo}
  <hr style="border:0;border-top:1px solid #e5e7eb;margin:24px 0;">
  <p style="font-size:12px;color:#667085;line-height:1.6;">
    Este conteúdo é informativo e não garante resultados futuros.
    Investimentos envolvem riscos. Avalie as condições de cada produto
    antes de tomar uma decisão.
  </p>
</div>`.trim();

  return {
    json: {
      nome: cliente.nome ?? "",
      email: cliente.email ?? "",
      perfil: cliente.perfil ?? "",
      saldo: cliente.saldo ?? "",
      investimentos: cliente.investimentos ?? [],
      assunto_email:
        cliente.assunto ??
        `Informações sobre investimentos para ${cliente.nome ?? "cliente"}`,
      corpo_email_texto: texto,
      corpo_email_html: html
    }
  };
});

const entrada = $input.all();
const resultado = [];

for (const item of entrada) {
  const dados = item.json;

  // Caso os clientes ainda estejam agrupados numa lista
  const lista = Array.isArray(dados.clientes)
    ? dados.clientes
    : Array.isArray(dados.body?.clientes)
      ? dados.body.clientes
      : null;

  if (lista) {
    for (const cliente of lista) {
      resultado.push({
        json: {
          ...cliente,
          investimentos:
            cliente.investimentos ??
            dados.investimentos ??
            [],
          mensagem:
            cliente.mensagem ??
            dados.mensagem ??
            ""
        }
      });
    }
  } else {
    // Caso já exista um item por cliente, preserva tudo
    resultado.push({
      json: { ...dados }
    });
  }
}

return resultado;
